look.customCSS:
/* ───── 月下星路 · 第一批 ───── */
/* 底色：褪色的米灰，颗粒、暗角、零星糖果色星星；一轮太近太亮的月亮压在右上 */
[data-wk="chat"]{background:radial-gradient(circle at 82% 16%,#FFFBE6 0 46px,rgba(255,250,224,.55) 50px,rgba(255,248,220,.18) 120px,transparent 200px),url("data:image/svg+xml;base64,") 0 0/60px 60px,url("data:image/svg+xml;base64,") 0 0/240px 300px,radial-gradient(ellipse at 50% 45%,transparent 45%,rgba(40,36,28,.45) 100%),linear-gradient(180deg,#A79E8A,#8E8674) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一层旧玻璃，底边一道发虚的月光线 */
[data-wk="chathead"]{background:rgba(120,113,96,.55) !important;backdrop-filter:blur(6px) !important;-webkit-backdrop-filter:blur(6px) !important;border-bottom:none !important;box-shadow:0 1px 0 rgba(245,239,210,.5),0 4px 14px rgba(245,239,210,.25) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#F5EFD2 !important;letter-spacing:.12em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#E3DBC2 !important}
[data-wk="chatback"] svg{stroke:#F5EFD2 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chat"] [data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;margin-left:-6px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:0 0 0 2px #F5EFD2,0 0 10px 3px rgba(245,239,210,.55) !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important;margin-left:6px !important}

/* 头像：一轮月亮——月光一圈，外面一圈偏开的重影 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 3px #F5EFD2,0 0 14px 4px rgba(245,239,210,.6),5px -3px 0 5px rgba(245,239,210,.18) !important}
[data-wk="body"] [data-wk="avatar"] > img[data-wk="avatar"]{box-shadow:none !important}

/* 气泡：他是一团月光雾（边缘糊开、自己发光）；我是一块旧电视屏（深色、细细一道发光边）；底下排队跟着一串糖果色星星 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:14px !important;line-height:1.65 !important;letter-spacing:.08em !important;margin-bottom:10px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:radial-gradient(ellipse at 50% 40%,#FFFDF0,#F5EFD2 70%) !important;color:#3D3A33 !important;box-shadow:0 0 18px 6px rgba(245,239,210,.55),0 0 2px 1px rgba(255,255,255,.8) !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#3A3833,#26251F) !important;color:#E6DFC9 !important;box-shadow:inset 0 0 0 1px rgba(245,239,210,.7),0 0 10px rgba(245,239,210,.3),inset 0 0 18px rgba(183,156,255,.15) !important;padding:11px 18px !important;text-shadow:0 0 4px rgba(245,239,210,.4) !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;bottom:-12px !important;height:14px !important;background:url("data:image/svg+xml;base64,") 0 0/120px 16px repeat-x !important;filter:drop-shadow(0 0 3px rgba(255,255,255,.8)) !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{background:url("data:image/svg+xml;base64,") right 0 top 0/120px 16px repeat-x !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}

/* 时间：时间后面跟一句永远不变的「（这里来过）」 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#E6DFC9 !important;font-size:11.5px !important;letter-spacing:.2em !important;text-shadow:0 0 6px rgba(245,239,210,.6) !important}
[data-wk="time"] > span::after{content:"  （这里来过）" !important;opacity:.6 !important;letter-spacing:.1em !important}
/* 已读：一颗星星睁开眼；没读：闭着 */
[data-wk="meta"]{color:#E6DFC9 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:16px !important;height:16px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px #FFE45C) !important}
[data-wk="meta"][data-read="0"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#E6DFC9 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#F5EFD2 !important;border:none !important;border-radius:14px !important;box-shadow:0 0 14px 4px rgba(245,239,210,.5) !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B79CFF !important}

/* 动描：一张旧拍立得的背面——白边、褪色的字，像照片背后写的 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;background:#EDE7D6 !important;border:none !important;border-radius:2px !important;box-shadow:0 0 0 6px #F7F3E8,0 4px 10px rgba(0,0,0,.25) !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#8A8270 !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:6px 14px !important;margin:8px 0 !important;transform:rotate(-1deg) !important}
[data-wk="myactink"]{transform:rotate(1deg) !important;color:#7E7A92 !important}
/* 系统提示：梦里的告示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#E6DFC9 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.12em !important}
[data-wk="sysnotetext"]::before{content:"⟡ " !important;color:#FFE45C !important}
[data-wk="sysnotetext"]::after{content:" ⟡" !important;color:#FFE45C !important}
[data-wk="narrbar"]{background:rgba(120,113,96,.7) !important;border-top:1px solid rgba(245,239,210,.4) !important}
[data-wk="narrkind"]{border:1px solid rgba(245,239,210,.4) !important;border-radius:999px !important;background:transparent !important;color:#E6DFC9 !important}
[data-wk="narrkind"][data-on="1"]{background:#F5EFD2 !important;color:#3D3A33 !important}

/* 底栏：同一层旧玻璃；左一颗粉星加号、雾色输入框、右边月亮发送、带星星的对话框回复 */
[data-wk="composer"]{background:rgba(120,113,96,.55) !important;backdrop-filter:blur(6px) !important;-webkit-backdrop-filter:blur(6px) !important;border-top:none !important;box-shadow:0 -1px 0 rgba(245,239,210,.5),0 -4px 14px rgba(245,239,210,.2) !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:rgba(245,239,210,.25) !important;border:1px solid rgba(245,239,210,.5) !important;border-radius:14px !important;color:#FFFBEA !important}
[data-wk="chatinput"]::placeholder{color:#EDE6CE !important}
[data-wk="chatplus"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAzMCc+PGcgdHJhbnNmb3JtPSd0cmFuc2xhdGUoMyAzKSc+PHBhdGggdHJhbnNmb3JtPSdzY2FsZSgyLjQpJyBkPSdNNSAwIEw2LjIgMy42IEwxMCAzLjggTDcgNi4yIEw4IDEwIEw1IDcuOCBMMiAxMCBMMyA2LjIgTDAgMy44IEwzLjggMy42WicgZmlsbD0nI0ZGN0FDOCcvPjwvZz48L3N2Zz4=") center/contain no-repeat !important;filter:drop-shadow(0 0 4px #FF7AC8) !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}

/* 打电话那一屏：同一片褪色的梦，月亮更近 */
[data-wk="call"][data-video="0"]{background:radial-gradient(circle at 50% 20%,#FFFBE6 0 70px,rgba(255,250,224,.5) 76px,transparent 220px),url("data:image/svg+xml;base64,") 0 0/60px 60px,url("data:image/svg+xml;base64,") 0 0/240px 300px,linear-gradient(180deg,#A79E8A,#8E8674) !important}
[data-wk="calltitle"]{color:#3D3A33 !important;letter-spacing:.15em !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 5px #F5EFD2,0 0 40px 14px rgba(245,239,210,.7),12px -8px 0 10px rgba(245,239,210,.2) !important}
[data-wk="callbtns"] button > span:first-child{background:#F5EFD2 !important;border-radius:50% !important;box-shadow:0 0 16px 4px rgba(245,239,210,.6) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#3D3A33 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#3A3833 !important;box-shadow:inset 0 0 0 1.5px #FF7AC8,0 0 14px #FF7AC8 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#FF7AC8 !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:#3D3A33 !important}
[data-wk="callbubble"]{background:#F5EFD2 !important;color:#3D3A33 !important;border:none !important;border-radius:14px !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#3A3833 !important;color:#E6DFC9 !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:#EDE7D6 !important;border:none !important;border-radius:2px !important;box-shadow:0 0 0 5px #F7F3E8 !important;padding:8px 14px !important;color:#8A8270 !important;font-size:12px !important;font-style:italic !important;text-align:left !important}
[data-wk="noteink"]{color:#E6DFC9 !important}
[data-wk="callact"]{color:#B79CFF !important}
